int main() {
    vector<int> a = {1, 2, 4, 5, 7, 8, 11};
    int x = 9;
    int l = 0, r = (int)a.size() - 1;
    while (l < r) {
        int s = a[l] + a[r];
        if (s == x) {
            cout << a[l] << ' ' << a[r] << '\n';
            l++;
            r--;
        } else if (s < x) {
            l++;
        } else {
            r--;
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    long long S;
    cin >> n >> S;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;
    long long s = 0;
    int best = 0, start = -1;
    for (int r = 0, l = 0; r < n; r++) {
        s += a[r];
        while (s > S) s -= a[l++];
        if (r - l + 1 > best) {
            best = r - l + 1;
            start = l;
        }
    }
    cout << best << ' ' << start << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<int> a = {4, 4, 1, 3, 3, 3, 9, 1};
    int k = 3, n = a.size();
    long long s = 0;
    unordered_map<int, int> cnt;
    for (int i = 0; i < k; i++) {
        s += a[i];
        cnt[a[i]]++;
    }
    long long best = s;
    vector<int> kinds = {(int)cnt.size()};
    for (int r = k; r < n; r++) {
        s += a[r] - a[r - k];
        best = max(best, s);
        cnt[a[r]]++;
        if (--cnt[a[r - k]] == 0) cnt.erase(a[r - k]);
        kinds.push_back(cnt.size());
    }
    cout << best << '\n';
    for (int x : kinds) cout << x << ' ';
    cout << '\n';
    return 0;
}
